struct Const {
  static constexpr uintptr_t kRefNullBits = ~uintptr_t(0);

  Const() : Const(Type::I32, uint32_t(0)) {}

  static Const I32(uint32_t val = 0, const Location& loc = Location()) { return Const(Type::I32, val, loc); }
  static Const I64(uint64_t val = 0, const Location& loc = Location()) { return Const(Type::I64, val, loc); }
  static Const F32(uint32_t val = 0, const Location& loc = Location()) { return Const(Type::F32, val, loc); }
  static Const F64(uint64_t val = 0, const Location& loc = Location()) { return Const(Type::F64, val, loc); }
  static Const V128(v128 val, const Location& loc = Location()) { return Const(Type::V128, val, loc); }

  Type type() const { return type_; }
  Type lane_type() const { assert(type_ == Type::V128); return lane_type_; }
  int lane_count() const { switch (lane_type()) { case Type::I8: return 16; case Type::I16: return 8; case Type::I32: return 4; case Type::I64: return 2; case Type::F32: return 4; case Type::F64: return 2; default: WABT_UNREACHABLE; } }

  uint32_t u32() const { return data_.u32(0); }
  uint64_t u64() const { return data_.u64(0); }
  uint32_t f32_bits() const { return data_.f32_bits(0); }
  uint64_t f64_bits() const { return data_.f64_bits(0); }
  uintptr_t ref_bits() const { return data_.To<uintptr_t>(0); }
  v128 vec128() const { return data_; }

  template <typename T> T v128_lane(int lane) const { return data_.To<T>(lane); }

  void set_u32(uint32_t x) { From(Type::I32, x); }
  void set_u64(uint64_t x) { From(Type::I64, x); }
  void set_f32(uint32_t x) { From(Type::F32, x); }
  void set_f64(uint64_t x) { From(Type::F64, x); }

  void set_v128_u8(int lane, uint8_t x) { set_v128_lane(lane, Type::I8, x); }
  void set_v128_u16(int lane, uint16_t x) { set_v128_lane(lane, Type::I16, x); }
  void set_v128_u32(int lane, uint32_t x) { set_v128_lane(lane, Type::I32, x); }
  void set_v128_u64(int lane, uint64_t x) { set_v128_lane(lane, Type::I64, x); }
  void set_v128_f32(int lane, uint32_t x) { set_v128_lane(lane, Type::F32, x); }
  void set_v128_f64(int lane, uint64_t x) { set_v128_lane(lane, Type::F64, x); }

  void set_f32(ExpectedNan nan) { set_f32(0); set_expected_nan(0, nan); }
  void set_f64(ExpectedNan nan) { set_f64(0); set_expected_nan(0, nan); }
  void set_funcref() { From<uintptr_t>(Type::FuncRef, 0); }
  void set_externref(uintptr_t x) { From(Type::ExternRef, x); }
  void set_extern(uintptr_t x) { From(Type(Type::ExternRef, Type::ReferenceNonNull), x); }
  void set_null(Type type) { From<uintptr_t>(type, kRefNullBits); }

  bool is_expected_nan(int lane = 0) const { return expected_nan(lane) != ExpectedNan::None; }
  ExpectedNan expected_nan(int lane = 0) const { return lane < 4 ? nan_[lane] : ExpectedNan::None; }
  void set_expected_nan(int lane, ExpectedNan nan) { if (lane < 4) { nan_[lane] = nan; } }

  Location loc;

 private:
  template <typename T> void set_v128_lane(int lane, Type lane_type, T x) { lane_type_ = lane_type; From(Type::V128, x, lane); set_expected_nan(lane, ExpectedNan::None); }
  template <typename T> Const(Type type, T data, const Location& loc = Location()) : loc(loc) { From<T>(type, data); }
  template <typename T> void From(Type type, T data, int lane = 0) { static_assert(sizeof(T) <= sizeof(data_), "Invalid cast!"); assert((lane + 1) * sizeof(T) <= sizeof(data_)); type_ = type; data_.From<T>(lane, data); set_expected_nan(lane, ExpectedNan::None); }

  Type type_;
  Type lane_type_;
  v128 data_;
  ExpectedNan nan_[4];
};

