import random
import struct
from typing import List

# We generate valid WebAssembly binaries or wasm-like buffers since many stubs
# parse or consume arbitrary binary data as WebAssembly or custom section bytes.
# Strategy:
# - With high probability, emit a minimal valid WASM module (magic, version, and
#   a few small well-formed sections).
# - Sometimes emit a valid WAT text snippet (useful for WastLexer buffer stubs).
# - Occasionally emit arbitrary but structured bytes (custom section with name+payload),
#   still a valid wasm with a single custom section.
# - Keep size <= 4096.
#
# Minimal valid wasm module layout used:
#  00 61 73 6D  -> magic
#  01 00 00 00  -> version 1
#  optional sections:
#   - Type section with one function type (no params, no results or small variants)
#   - Function section mapping one function to the type
#   - Code section with a tiny body (locals=0, body: end)
#   - Optional name custom section
# We also provide helper to emit LEB128, section writer utilities, etc.

# LEB128 helpers

def u32_leb(n: int) -> bytes:
    # unsigned LEB128 for 32-bit
    out = bytearray()
    while True:
        b = n & 0x7F
        n >>= 7
        if n:
            out.append(b | 0x80)
        else:
            out.append(b)
            break
    return bytes(out)


def s32_leb(n: int) -> bytes:
    # signed LEB128 32-bit
    out = bytearray()
    more = True
    while more:
        b = n & 0x7F
        n >>= 7
        sign = (b & 0x40) != 0
        if (n == 0 and not sign) or (n == -1 and sign):
            more = False
        else:
            b |= 0x80
        out.append(b & 0xFF)
    return bytes(out)


def vec(data: List[bytes]) -> bytes:
    return u32_leb(len(data)) + b"".join(data)


def name_bytes(s: str) -> bytes:
    b = s.encode('utf-8', 'surrogatepass')
    return u32_leb(len(b)) + b

# Section writers

def section(id_byte: int, payload: bytes) -> bytes:
    return bytes([id_byte]) + u32_leb(len(payload)) + payload


def type_section(func_sigs: List[bytes]) -> bytes:
    # type section id = 1
    return section(1, vec(func_sigs))


def func_type(params: List[int], results: List[int]) -> bytes:
    # 0x60, vec(param types), vec(result types)
    return bytes([0x60]) + vec([bytes([p]) for p in params]) + vec([bytes([r]) for r in results])


def function_section(type_indices: List[int]) -> bytes:
    # section id = 3
    return section(3, vec([u32_leb(i) for i in type_indices]))


def code_function_body(locals_decl: List[tuple], body: bytes) -> bytes:
    # locals_decl: list of (count, valtype)
    decl = bytearray()
    decl += u32_leb(len(locals_decl))
    for cnt, vt in locals_decl:
        decl += u32_leb(cnt)
        decl += bytes([vt])
    func_bytes = bytes(decl) + body + b"\x0b"  # end
    return u32_leb(len(func_bytes)) + func_bytes


def code_section(bodies: List[bytes]) -> bytes:
    # id = 10
    return section(10, vec(bodies))


def export_section(exports: List[bytes]) -> bytes:
    # id = 7
    return section(7, vec(exports))


def export_func(name: str, func_index: int) -> bytes:
    # name, kind=0 func, index
    return name_bytes(name) + bytes([0x00]) + u32_leb(func_index)


def custom_section(name: str, payload: bytes) -> bytes:
    # id = 0, content = name + payload
    content = name_bytes(name) + payload
    return section(0, content)

# Build minimal valid wasm variants

def build_minimal_wasm(r: random.Random) -> bytes:
    magic = b"\x00asm"  # 00 61 73 6d
    version = b"\x01\x00\x00\x00"

    # Choose small random signature
    # valtype codes: i32=0x7F, i64=0x7E, f32=0x7D, f64=0x7C
    valtypes = [0x7F, 0x7E, 0x7D, 0x7C]
    params: List[int] = []
    results: List[int] = []
    # Randomly 0-2 params
    for _ in range(r.randrange(0, 3)):
        params.append(r.choice(valtypes))
    # Randomly 0-1 result (wasm MVP single or zero results)
    if r.random() < 0.6:
        # often zero results
        results = []
    else:
        results = [r.choice(valtypes)]

    tsec = type_section([func_type(params, results)])
    fsec = function_section([0])  # one func of type 0

    # Build tiny body: optionally use simple ops then end
    body_ops = bytearray()
    # Push constants matching result to make validation trivial
    if results:
        rt = results[0]
        if rt == 0x7F:  # i32.const 0
            body_ops += b"\x41" + s32_leb(0)
        elif rt == 0x7E:  # i64.const 0
            body_ops += b"\x42" + s32_leb(0)
        elif rt == 0x7D:  # f32.const 0.0
            body_ops += b"\x43" + struct.pack('<I', 0)
        elif rt == 0x7C:  # f64.const 0.0
            body_ops += b"\x44" + struct.pack('<Q', 0)
    # Optionally add drop/nop
    if r.random() < 0.3:
        body_ops += b"\x01"  # nop
    csec = code_section([code_function_body([], bytes(body_ops))])

    sections = [tsec, fsec, csec]

    # Optionally add export for the function
    if r.random() < 0.7:
        ename = "f" if r.random() < 0.5 else "main"
        esec = export_section([export_func(ename, 0)])
        sections.insert(2, esec)

    # Optionally add a small custom/name section
    if r.random() < 0.5:
        # Minimal name section with module name subsection is complex; instead emit generic custom
        payload = r.randbytes(r.randrange(0, 32)) if hasattr(r, 'randbytes') else bytes([r.randrange(256) for _ in range(r.randrange(0, 32))])
        sections.append(custom_section("custom", payload))

    return magic + version + b"".join(sections)


def build_custom_only_wasm(r: random.Random) -> bytes:
    # Valid wasm with just a custom section (allowed) after header
    magic = b"\x00asm"
    version = b"\x01\x00\x00\x00"
    # a few random custom sections
    n = r.randrange(1, 4)
    sections = []
    for i in range(n):
        name = f"c{i}"
        payload_len = r.randrange(0, 64)
        payload = r.randbytes(payload_len) if hasattr(r, 'randbytes') else bytes([r.randrange(256) for _ in range(payload_len)])
        sections.append(custom_section(name, payload))
    return magic + version + b"".join(sections)


def build_wat_text(r: random.Random) -> bytes:
    # Produce a small valid WAT module text useful for WastLexer and parser buffers
    # Vary between empty module, exported func, memory, globals.
    pieces = []
    pieces.append("(module")
    if r.random() < 0.6:
        # add a func
        if r.random() < 0.5:
            pieces.append(" (func $f)")
        else:
            # typed func returning i32 0
            pieces.append(" (func (export \"main\") (result i32) i32.const 0)")
    if r.random() < 0.3:
        pieces.append(" (memory 1)")
    if r.random() < 0.3:
        pieces.append(" (global (mut i32) (i32.const 0))")
    pieces.append(")")
    txt = "".join(pieces)
    return txt.encode('utf-8')


def build_arbitrary_bytes(r: random.Random) -> bytes:
    # Opaque but structured: choose between raw random bytes (>=1),
    # or a small UTF-8 string for UTF-8 validator consumers.
    if r.random() < 0.5:
        n = r.randrange(1, 512)
        return r.randbytes(n) if hasattr(r, 'randbytes') else bytes([r.randrange(256) for _ in range(n)])
    else:
        # ASCII/UTF-8 string
        alphabet = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-.\n\t"
        n = r.randrange(1, 512)
        return bytes(alphabet[r.randrange(0, len(alphabet))] for _ in range(n))


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    choice = r.random()
    if choice < 0.55:
        data = build_minimal_wasm(r)
    elif choice < 0.7:
        data = build_custom_only_wasm(r)
    elif choice < 0.85:
        data = build_wat_text(r)
    else:
        data = build_arbitrary_bytes(r)
    # Ensure size <= 4096
    if len(data) > 4096:
        data = data[:4096]
    # Ensure non-empty
    if not data:
        data = b"\0"
    return data
